// Extends the existing hand-written "Cross-Cut Round 16: Prompt Caching Matrix" folder in
// provider-harness.json (found by name, not generated by this file) with real cache-HIT
// verification. The existing rows in that folder are single-shot: they send one request with
// a 2-word "Long ctx" system string and cache_control attached, which only proves the field is
// accepted - "Long ctx" is nowhere near any provider's minimum cacheable-prompt size, and there
// is no second request to confirm a cache read ever happens.
//
// These new rows instead run 3 independent, same-session requests per backend, all sharing the
// identical long, stable {{cachePrefix}} system block already defined as a collection variable
// (originally added for exactly this purpose - see its own inline description). Round 1 is the
// cache write (informational only - a fresh cache has nothing to hit yet). Rounds 2 and 3 reuse
// the identical prefix with a different question each time and assert prompt_tokens_details.
// cached_tokens > 0, proving the cache is actually being read, twice in a row.
//
// Every row goes through Bifrost's unified /v1/chat/completions (one request shape regardless
// of backend), unlike the Direct-Provider vs Bifrost Token Parity Matrix (token-parity-matrix.
// mjs), which is a different feature entirely - this one only exercises Bifrost itself.

const J = (v) => JSON.stringify(v);

// Explicit cache_control (Anthropic-family: native "ephemeral" breakpoints) vs automatic/
// implicit caching (OpenAI, Gemini - no cache_control needed, just a stable repeated prefix
// over the provider's minimum cacheable size; {{cachePrefix}} comfortably exceeds OpenAI's
// 1024-token minimum). Model choices reuse exact IDs already proven elsewhere in this
// collection (e.g. the existing Round 16 rows, effortModels in augment-provider-harness.mjs)
// rather than guessing new ones.
// cacheReadGuaranteed decides between a hard assertion and a reported measurement, and
// is a separate axis from explicitCache. An accepted cache_control breakpoint is a
// contract: a repeat of the same prefix must read it back, so a miss is a real defect.
// Gemini's implicit caching is not. Google promises only to "automatically pass on cost
// savings if your request hits caches" and frames its own advice as ways to "improve
// implicit cache hit likelihood" (https://ai.google.dev/gemini-api/docs/caching).
//
// Measured here directly, with and without Bifrost in the path, byte-identical repeats of
// the same prefix alternate between a miss and a full hit with no discernible pattern -
// the same behaviour crossprovider-cache-matrix.mjs already records from its own runs
// (gemini-2.5-flash 0%/97%/0%/0%). Asserting a hit on rounds 2 AND 3 of only 3 rounds
// therefore fails intermittently for something Bifrost does not control. That file solves
// it by running more rounds and asserting only "cached at least once"; this one has just
// 3 rounds, so the Gemini row reports instead of asserting.
//
// OpenAI stays asserted despite also being implicit: it has been stable across runs here,
// and the token-parity suite additionally pins it with an affinity key. This is a remedy
// for a documented non-guarantee that was observed flapping, not a blanket implicit-cache
// policy.
const CACHING_BACKENDS = [
  { key: "openai", label: "OpenAI", model: "openai/gpt-4o-mini", explicitCache: false, cacheReadGuaranteed: true },
  { key: "anthropic", label: "Anthropic", model: "anthropic/claude-haiku-4-5", explicitCache: true, cacheReadGuaranteed: true },
  { key: "gemini", label: "Gemini", model: "gemini/gemini-2.5-flash", explicitCache: false, cacheReadGuaranteed: false },
  // Not read-guaranteed, unlike the other two explicit-cache backends, and the difference is the
  // deployment rather than the model. This key is configured at location=global, which routes each
  // request to whichever region has capacity, and an Anthropic cache entry lives in the region that
  // wrote it - so a repeat is only a hit when it happens to land on a region already holding the
  // prefix. Measured on a guaranteed-cold prefix: round 3 missed 4 times out of 5, and raising the
  // settle from 1.2s to 5s changed nothing (so it is not write propagation). Sending one cold prefix
  // 12 times in a row gave MMMHHMHMHHHH - 1 hit in the first 4, 6 in the last 8, the hit rate
  // climbing as more regions warm. Three requests cannot reliably read back a cold prefix here, so
  // the row asserts what Bifrost actually controls (below) and reports the hit.
  { key: "vertex", label: "Vertex (Claude)", model: "vertex/claude-sonnet-4-6", explicitCache: true, cacheReadGuaranteed: false },
  { key: "bedrock", label: "Bedrock (Claude)", model: "bedrock/global.anthropic.claude-haiku-4-5-20251001-v1:0", explicitCache: true, cacheReadGuaranteed: true },
];

// Floor for "the prefix was on the wire". Deliberately far below {{cachePrefix}}'s real size and
// far above a bare question (~20 tokens), so it separates the two cases without being sensitive to
// tokenizer differences across the five backends.
const PREFIX_MIN_PROMPT_TOKENS = 500;

// A cache write is not readable the instant the writing response returns, and these rows fire back
// to back with nothing between them. Observed on vertex/claude-sonnet-4-6: round 2 came back with
// cached_write_tokens 4742 and cached_tokens 0, meaning Vertex wrote the prefix a second time
// rather than reading round 1's copy. That is propagation latency, not a dropped breakpoint - the
// same cell reads back fine in the cross-provider matrix, which has carried this settle since it
// was written (crossprovider-cache-matrix.mjs). Applied to the read rounds only; round 1 has
// nothing to wait for. Busy-wait rather than setTimeout because a Postman prerequest script has no
// async escape hatch that blocks the request.
const SETTLE = `var __t = Date.now(); while (Date.now() - __t < 1200) { /* settle: let the previous round's cache write land */ }`;

const QUESTIONS = [
  "In one sentence, what is this operating manual mostly about?",
  "Name one specific rule this manual mentions about formatting.",
  "In one sentence, summarize the tone requirements this manual describes.",
];

// The prefix rides a system MESSAGE, not a top-level `system` field. These rows post to
// /v1/chat/completions, whose schema has no top-level `system` - that is the Anthropic Messages
// shape. An unknown top-level key lands in ExtraParams and is dropped unless passthrough-extra-
// params is on, so the earlier top-level form silently sent no prefix at all: rounds 2-3 reported
// prompt_tokens of 17-20 and the model answered "I don't see any manual attached", which then read
// as a cache miss on all five backends when nothing had ever been cached.
//
// cache_control rides the content block (ChatContentBlock carries it on this surface), matching
// how the hand-written Round 16 rows in the collection already attach cache breakpoints.
const systemMessage = (explicitCache) => {
  const block = { type: "text", text: "{{cachePrefix}}" };
  if (explicitCache) block.cache_control = { type: "ephemeral" };
  return { role: "system", content: [block] };
};

const extractScript = `
var j = pm.response.json();
var u = j.usage || {};
var cached = (u.prompt_tokens_details && u.prompt_tokens_details.cached_tokens) || 0;
var written = (u.prompt_tokens_details && (u.prompt_tokens_details.cached_write_tokens || u.prompt_tokens_details.cache_write_tokens)) || 0;
var prompt = u.prompt_tokens || 0;`.trim();

// These three rounds are one stateful chain - round 1 writes the prefix, rounds 2 and 3 read it
// back - but nothing in the harness inferred that, because the link lived only in the rounds'
// shared prompt text. sliceByCost (lib/shard-cost.mjs) bin-packs rows individually and promises
// only original order WITHIN a slice, and --rerun-failed selects exactly the rows that failed, so
// either one can hand round 3 to a newman process that never ran round 1. Round 3 then meets a
// cold prefix; its ephemeral breakpoint writes the prefix instead of reading it and reports
// cached_tokens 0, which fails the assertion for a reason that has nothing to do with caching.
// Worse, it is self-perpetuating: the row failed, so the next --rerun-failed pass selects it
// alone again, and it can never go green.
//
// So the link is now declared the way this harness already declares request ordering - as a
// chained collection variable (lib/chained-vars.mjs). Each round publishes one on success and the
// next round consumes it, which buys both halves of the fix from machinery that already exists:
// filter-collection.mjs pulls a consumer's producers into any sliced or rerun selection, and
// augment-provider-harness.mjs guards a consumer whose producer still did not run, so a partial
// selection reports "prerequisite did not set its chained variable" once instead of a misleading
// cache miss.
//
// The variable rides the URL as a query parameter rather than the request body on purpose. This
// is a prompt-caching test: the cached prefix and the payload around it have to stay
// byte-identical from round to round, and a variable interpolated into the body would change the
// bytes every run. Bifrost ignores the parameter, and the "cross-cut" route-shape matcher in
// filter-collection.mjs already anchors on /v1/chat/completions(\\?|$), so classification is
// unaffected.
const chainVar = (backendKey, round) => `cacheChain_${backendKey}_r${round}`;

// Published on any non-error response, because what the next round requires is simply that the
// prefix reached the provider - not that this round's own cache assertion passed. A round that
// 4xx'd publishes nothing, and the guard downstream then names it as the unmet prerequisite.
const publishChain = (backendKey, round) =>
  `if (pm.response.code < 400) { pm.collectionVariables.set(${J(chainVar(backendKey, round))}, "sent-" + prompt); }`;

const urlFor = (backendKey, round) => {
  const base = { raw: "{{baseUrl}}/v1/chat/completions", host: ["{{baseUrl}}"], path: ["v1", "chat", "completions"] };
  if (round === 1) return base;
  const consumed = `{{${chainVar(backendKey, round - 1)}}}`;
  return { ...base, raw: `${base.raw}?_chain=${consumed}`, query: [{ key: "_chain", value: consumed }] };
};

export function buildPromptCachingHitVerificationItems() {
  const items = [];

  for (const backend of CACHING_BACKENDS) {
    for (let round = 1; round <= 3; round++) {
      const body = {
        model: backend.model,
        max_tokens: 300,
        messages: [systemMessage(backend.explicitCache), { role: "user", content: QUESTIONS[round - 1] }],
      };
      const isReadRound = round >= 2;
      const script = isReadRound
        ? `
${extractScript}
pm.test(${J(`Prompt caching hit-verification: ${backend.key} round ${round} succeeds`)}, function () {
  pm.expect(pm.response.code, "request failed: " + pm.response.text()).to.be.below(400);
});
if (pm.response.code < 400) {
  // Assert the prefix actually went out BEFORE judging the cache. A dropped prefix and a genuine
  // cache miss both surface as cached_tokens 0, and conflating them is how a wire-shape bug hid
  // here as five backends' worth of "caching is broken". {{cachePrefix}} is far over 1024 tokens,
  // so a prompt this small means the prefix never left the harness.
  pm.test(${J(`Prompt caching hit-verification: ${backend.key} round ${round} - prefix was actually sent`)}, function () {
    pm.expect(prompt, "prompt_tokens=" + prompt + " (usage=" + JSON.stringify(u) + ") - {{cachePrefix}} is >1024 tokens, so this request cannot have carried it; the cache assertion below would be meaningless").to.be.above(${PREFIX_MIN_PROMPT_TOKENS});
  });
  ${
    backend.cacheReadGuaranteed
      ? `pm.test(${J(`Prompt caching hit-verification: ${backend.key} round ${round} - cache read hit (cached_tokens > 0)`)}, function () {
    pm.expect(cached, "prompt=" + prompt + " cached=" + cached + " (usage=" + JSON.stringify(u) + ") - identical {{cachePrefix}} was sent in round 1, expected a cache read here").to.be.above(0);
  });`
      : // Best-effort caching on this backend: a miss is allowed behaviour, so it must not fail
        // the run. Still assert what IS invariant regardless of whether the cache engaged - the
        // counter must be a real number and can never exceed the prompt it came from - so a
        // nonsense value is still caught. The hit/miss is logged so a permanent regression to
        // 0% stays visible in the run output instead of disappearing entirely.
        //
        // An explicit-breakpoint backend gets one more assertion than an implicit one, because
        // more of its behaviour is Bifrost's to get right. Whether a repeat LANDS on the region
        // holding the entry is the deployment's business, but whether cache_control survived the
        // conversion and reached the provider at all is not: an honoured breakpoint always books
        // the prefix as either a write or a read, so a dropped one is the case where both counters
        // are zero. That keeps a real regression - Bifrost silently losing the breakpoint - failing
        // the run, which a bare hit/miss report would have let through.
        `${backend.explicitCache ? `pm.test(${J(`Prompt caching hit-verification: ${backend.key} round ${round} - cache breakpoint honoured (write or read recorded)`)}, function () {
    pm.expect(cached + written, "cached=" + cached + " written=" + written + " (usage=" + JSON.stringify(u) + ") - neither counter moved, so cache_control never reached the provider").to.be.above(0);
  });
  ` : ""}pm.test(${J(`Prompt caching hit-verification: ${backend.key} round ${round} - cached_tokens coherent (best-effort cache, hit not guaranteed)`)}, function () {
    pm.expect(cached, "cached=" + cached + " (usage=" + JSON.stringify(u) + ")").to.be.a("number").that.is.at.least(0);
    pm.expect(cached, "cached=" + cached + " exceeds prompt=" + prompt + " (usage=" + JSON.stringify(u) + ")").to.be.at.most(prompt);
  });
  console.log("IMPLICIT_CACHE_OBSERVATION", JSON.stringify({ backend: ${J(backend.key)}, model: ${J(backend.model)}, round: ${round}, prompt: prompt, cached: cached, hit: cached > 0 }));`
  }
}
${round < 3 ? publishChain(backend.key, round) : ""}`.trim()
        : `
${extractScript}
pm.test(${J(`Prompt caching hit-verification: ${backend.key} round 1 (write) succeeds`)}, function () {
  pm.expect(pm.response.code, "request failed: " + pm.response.text()).to.be.below(400);
});
${publishChain(backend.key, round)}`.trim();

      items.push({
        name: `Prompt caching hit-verification: ${backend.key}/${backend.model.split("/")[1]} round ${round}${isReadRound ? " (read)" : " (write)"}`,
        event: [
          ...(isReadRound
            ? [{ listen: "prerequest", script: { type: "text/javascript", exec: [SETTLE] } }]
            : []),
          { listen: "test", script: { type: "text/javascript", exec: script.split("\n") } },
        ],
        request: {
          method: "POST",
          header: [{ key: "Content-Type", value: "application/json" }],
          body: { mode: "raw", raw: JSON.stringify(body, null, 2) },
          url: urlFor(backend.key, round),
        },
      });
    }
  }

  return items;
}
